<?php session_start();if(!empty($_SESSION['admin_id'])){header('Location:dashboard.php');exit;}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Giriş — Erdem Boutique</title><link rel="stylesheet" href="admin.css"></head><body class="admin-login"><div class="login-card"><div class="admin-logo">ERDEM<small>BOUTIQUE</small></div><p>Yönetim Paneli</p><form id="loginForm"><label>Kullanıcı adı<input id="username" autocomplete="username" required></label><label>Şifre<input id="password" type="password" autocomplete="current-password" required></label><button>Giriş Yap</button><div id="loginError" class="error"></div></form></div><script>loginForm.addEventListener('submit',async e=>{e.preventDefault();loginError.textContent='';let r=await fetch('api.php?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});let d=await r.json();if(d.ok)location.href='dashboard.php';else loginError.textContent=d.error||'Giriş başarısız.'});</script></body></html>